// #3115: a VarId's name is UTF-8 text (§2a), and every construction holds to it.
//
// Before #3115 NewVarId and Var accepted any Go string, so a name reify refuses could be built:
// quote wrote its raw bytes, and ClauseFromValue and SubstFromValue then refused what the same core
// had encoded. The law, over listed names and generated byte strings:
//   - a name is accepted iff it is valid UTF-8 (stated here from the spec: utf8.ValidString);
//   - ParseVarId refuses by name (*VarIdError), and NewVarId and Var panic with that error;
//   - every accepted name round-trips: reify(quote(v)) == v, and the clause and subst codecs decode
//     what they encode, and two distinct names never quote to the same bytes.
package contract

import (
	"errors"
	"math/rand"
	"testing"
	"unicode/utf8"

	codec "github.com/bitspark/ontos/codec/go"
)

var varIdListed = []string{
	"X", "é", "😀", "�", "", "퟿", "", "\U0010ffff",
	"\xff", "\xc3\x28", "\xc0\x80", "\xed\xa0\x80", "\xed\xbf\xbf", "\xf4\x90\x80\x80", "\xe2\x82",
	"a\xed\xa0\x80b",
}

// varIdGenerated draws byte strings from an alphabet weighted towards UTF-8's structure (ASCII,
// continuation bytes, every lead class and the bytes UTF-8 never uses), so both verdicts occur often.
func varIdGenerated(n int) []string {
	alphabet := []byte{'a', 'Z', '0', 0x00, 0x7f, 0x80, 0x9f, 0xa0, 0xbf, 0xc0, 0xc2, 0xdf, 0xe0, 0xe2, 0xed, 0xef, 0xf0, 0xf4, 0xf5, 0xff}
	r := rand.New(rand.NewSource(3115))
	out := make([]string, n)
	for i := range out {
		b := make([]byte, r.Intn(7))
		for j := range b {
			b[j] = alphabet[r.Intn(len(alphabet))]
		}
		out[i] = string(b)
	}
	return out
}

func mustVarIdPanic(f func()) (err *VarIdError, panicked bool) {
	defer func() {
		if p := recover(); p != nil {
			panicked = true
			e, _ := p.(error)
			errors.As(e, &err)
		}
	}()
	f()
	return nil, false
}

func TestVarIdConstructionHoldsToTheDomain3115(t *testing.T) {
	names := append(append([]string{}, varIdListed...), varIdGenerated(3000)...)
	byQuote := map[string]string{}
	accepted, refused := 0, 0
	for _, name := range names {
		inDomain := utf8.ValidString(name)
		id, err := ParseVarId(name)
		if (err == nil) != inDomain {
			t.Fatalf("ParseVarId(%q): err=%v, but §2a says in-domain=%v", name, err, inDomain)
		}
		for _, form := range []struct {
			label string
			f     func()
		}{
			{"NewVarId", func() { NewVarId(name) }},
			{"Var", func() { Var(name) }},
		} {
			perr, panicked := mustVarIdPanic(form.f)
			if panicked == inDomain {
				t.Fatalf("%s(%q): panicked=%v, but §2a says in-domain=%v", form.label, name, panicked, inDomain)
			}
			if panicked && (perr == nil || perr.Name != name) {
				t.Fatalf("%s(%q) panicked without a *VarIdError naming it: %v", form.label, name, perr)
			}
		}
		if !inDomain {
			refused++
			var verr *VarIdError
			if !errors.As(err, &verr) || verr.Name != name {
				t.Fatalf("ParseVarId(%q) refused without a *VarIdError naming it: %v", name, err)
			}
			continue
		}
		accepted++
		v := VarFromID(id)
		q := Quote(v)
		if back, ok := Reify(q); !ok || !back.Equal(v) {
			t.Fatalf("%q: reify(quote(v)) != v (reify ok=%v)", name, ok)
		}
		if prior, dup := byQuote[string(codec.Encode(q))]; dup && prior != name {
			t.Fatalf("%q and %q are distinct VarIds that quote to the same bytes", name, prior)
		}
		byQuote[string(codec.Encode(q))] = name
		clause := Clause{Head: NewGoal("p", v)}
		if back, ok := ClauseFromValue(ClauseValue(clause)); !ok || !back.Head.Args[0].Equal(v) {
			t.Fatalf("%q: ClauseFromValue does not read back its own ClauseValue", name)
		}
		subst := Subst{id: Atom([]byte("a"))}
		back, err := SubstFromValue(SubstAsValue(subst))
		if err != nil || len(back) != 1 || back[id] == nil {
			t.Fatalf("%q: SubstFromValue does not read back its own SubstAsValue: %v", name, err)
		}
	}
	if accepted < 100 || refused < 100 {
		t.Fatalf("control: the generator must reach both verdicts often; accepted %d, refused %d", accepted, refused)
	}
}
